def order_changes(changes: list[tuple[int,int,int,int,int]]) -> list[int] | None:
    seen=set()
    for c in changes:
        if c[0] in seen or any(x<0 for x in c[1:]): return None
        seen.add(c[0])
    return [c[0] for c in sorted(changes,key=lambda c:(c[1],c[2],c[3],c[4],c[0]))]
